'use strict';
const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process');
const base=__dirname;
const config=JSON.parse(fs.readFileSync(path.join(base,'harness/config.json'),'utf8'));
const out=fs.openSync(path.join(base,'host-output.log'),'a');
const env={...process.env};
for(const k of ['ELECTRON_RUN_AS_NODE','VSCODE_IPC_HOOK_CLI','VSCODE_CLI'])delete env[k];
const args=[config.fixture,'--new-window','--disable-extensions','--disable-workspace-trust','--skip-welcome','--skip-release-notes','--disable-updates','--disable-gpu','--user-data-dir',path.join(base,'profile'),'--extensions-dir',path.join(base,'extensions'),'--extensionDevelopmentPath='+path.join(base,'harness'),'--extensionTestsPath='+path.join(base,'harness/suite.cjs')];
fs.writeFileSync(path.join(base,'launch.json'),JSON.stringify({executable:config.executable,args},null,2));
const child=cp.spawn(config.executable,args,{cwd:base,env,windowsHide:true,stdio:['ignore',out,out]});
fs.writeFileSync(path.join(base,'host.pid'),String(child.pid));
child.on('error',e=>{console.error(e.message);process.exitCode=1;});
child.on('exit',(code,signal)=>{console.log(JSON.stringify({hostExitCode:code,signal,resultPath:config.results}));process.exitCode=code??1;});
setTimeout(()=>{console.error('Disposable host timeout; terminating only the owned process.');child.kill();process.exitCode=1;},150000).unref();

