'use strict';
const vscode = require('vscode');
const fs = require('node:fs');
const path = require('node:path');
const config = JSON.parse(fs.readFileSync(path.join(__dirname, 'config.json'), 'utf8'));
const result = { format:'215-c2-native-v1', startedAt:new Date().toISOString(), version:vscode.version, hostCommit:config.hostCommit, profile:config.profile, cases:[], events:[], harnessErrors:[] };
const t0=Date.now();
const states=new Map();
const owned=[];
let currentCase='setup';
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const emit=(type,data={})=>{result.events.push({ms:Date.now()-t0,case:currentCase,type,...data});fs.writeFileSync(config.results,JSON.stringify(result,null,2));};
const state=t=>states.get(t);
const exists=n=>fs.existsSync(path.join(config.fixture,n));
const receipt=n=>exists(n)?fs.readFileSync(path.join(config.fixture,n),'utf8'):null;
async function until(fn,timeout=10000,label='condition'){
 const start=Date.now(); while(Date.now()-start<timeout){const r=fn();if(r)return r;await sleep(20);}throw Error('Timed out: '+label);
}
function quote(s){return "'"+s.replace(/'/g,"''")+"'";}
function writeMarker(name,value='yes'){return '[IO.File]::WriteAllText('+quote(path.join(config.fixture,name))+', '+quote(value)+')';}
function caseRecord(id,data){const row={id,...data};result.cases.push(row);emit('case-result',row);return row;}
async function makeTerminal(label,extra={}){
 const t=vscode.window.createTerminal({name:'C2 disposable '+label,shellPath:config.shell,shellArgs:['-NoLogo'],cwd:config.fixture,...extra});
 owned.push(t);states.set(t,{label,ready:false,busy:false,closed:false,starts:0,ends:0});
 t.show(false);
 await until(()=>t.shellIntegration||state(t).closed,12000,'shell integration '+label);
 if(state(t).closed)throw Error('Terminal closed during readiness '+label);
 state(t).ready=true;await sleep(250);
 emit('terminal-ready',{terminal:label,cwd:t.shellIntegration.cwd?.fsPath||null,processId:await t.processId});
 return t;
}
async function nativeInput(t,text){t.show(false);await vscode.commands.executeCommand('workbench.action.terminal.sendSequence',{text});emit('native-input',{terminal:state(t).label,text});}
async function execute(t,command,label){
 const ex=t.shellIntegration.executeCommand(command);
 emit('api-dispatch',{terminal:state(t).label,label,command});return ex;
}
async function commandDone(t,command,label){
 const initial=state(t).ends;await execute(t,command,label);
 await until(()=>state(t).ends>initial,12000,'end '+label);await sleep(150);
}
function snapshot(t){const s=state(t);return {ready:!!t.shellIntegration,busy:s.busy,closed:s.closed,starts:s.starts,ends:s.ends,cwd:t.shellIntegration?.cwd?.fsPath||null};}
// Proposed observable guards, not a production controller.
// Check and dispatch share a JS turn; host/PTY input is still concurrent.
function admission(t,actionId,command,control){
 if(control.seen.has(actionId))return {outcome:'duplicate',dispatched:false};
 control.seen.add(actionId);
 if(control.pending)return {outcome:'pending',dispatched:false};
 const s=state(t);
 if(s.closed||!t.shellIntegration||!s.ready||s.busy)return {outcome:s.closed?'closed':!t.shellIntegration?'unknown':'busy',dispatched:false};
 control.pending=true;
 try{control.execution=t.shellIntegration.executeCommand(command);return {outcome:'submitted',dispatched:true};}
 catch(e){control.pending=false;return {outcome:'error',dispatched:false,error:e.message};}
}
exports.run=async function(){
 const listeners=[
 vscode.window.onDidChangeTerminalShellIntegration(e=>{if(state(e.terminal))emit('integration',{terminal:state(e.terminal).label,cwd:e.shellIntegration?.cwd?.fsPath||null});}),
 vscode.window.onDidStartTerminalShellExecution(e=>{const s=state(e.terminal);if(!s)return;s.busy=true;s.starts++;emit('start',{terminal:s.label,command:e.execution.commandLine.value,cwd:e.execution.cwd?.fsPath||null});(async()=>{let output='';try{for await(const chunk of e.execution.read())output+=chunk;emit('output',{terminal:s.label,command:e.execution.commandLine.value,output});}catch(err){emit('read-error',{terminal:s.label,error:err.message});}})();}),
 vscode.window.onDidEndTerminalShellExecution(e=>{const s=state(e.terminal);if(!s)return;s.busy=false;s.ends++;emit('end',{terminal:s.label,command:e.execution.commandLine.value,exitCode:e.exitCode??null});}),
 vscode.window.onDidCloseTerminal(t=>{const s=state(t);if(s){s.closed=true;emit('close',{terminal:s.label});}})
 ];
 try{
  emit('metadata',{version:vscode.version,platform:process.platform,node:process.versions.node,electron:process.versions.electron||null,shell:config.shell,fixture:config.fixture});
  currentCase='idle-and-persistence';
  const t=await makeTerminal('persistent');
  await commandDone(t,writeMarker('idle.marker')+"; $env:C2_DISPOSABLE_VALUE='kept'; Set-Location "+quote(path.join(config.fixture,'subfolder')),'idle-first');
  const cwdAfter=t.shellIntegration.cwd?.fsPath||null;
  await commandDone(t,'[IO.File]::WriteAllText('+quote(path.join(config.fixture,'persistence.marker'))+", $env:C2_DISPOSABLE_VALUE + '|' + (Get-Location).Path + '|' + $PSVersionTable.PSVersion.ToString())",'persistence-next');
  caseRecord(currentCase,{idleMarker:receipt('idle.marker'),persistence:receipt('persistence.marker'),reportedCwd:cwdAfter,sameTerminal:true});

  currentCase='duplicate-clicks';
  const dup=await makeTerminal('duplicates');
  const control={seen:new Set(),pending:false};
  const dupCmd='[IO.File]::AppendAllText('+quote(path.join(config.fixture,'duplicate.marker'))+",'x'); Start-Sleep -Milliseconds 400";
  const d1=admission(dup,'action-a',dupCmd,control);
  const d2=admission(dup,'action-a',dupCmd,control);
  const d3=admission(dup,'action-b',dupCmd,control);
  await until(()=>exists('duplicate.marker'),8000,'duplicate marker');
  await until(()=>state(dup).ends>=1,8000,'duplicate completion');
  caseRecord(currentCase,{outcomes:[d1,d2,d3],receipt:receipt('duplicate.marker'),scope:'synthetic admission guard around real native dispatch'});

  currentCase='known-busy-guard';
  const busy=await makeTerminal('busy');
  const busyCmd=writeMarker('busy.started')+'; Start-Sleep -Milliseconds 1200; '+writeMarker('busy.completed');
  const busyEnd=state(busy).ends;
  await nativeInput(busy,busyCmd+'\r');
  await until(()=>state(busy).busy&&exists('busy.started'),8000,'native command start');
  const blocked=admission(busy,'blocked-busy',writeMarker('busy.run'),{seen:new Set(),pending:false});
  await until(()=>exists('busy.completed')&&state(busy).ends>busyEnd,8000,'busy survives');
  caseRecord(currentCase,{admission:blocked,foregroundCompleted:exists('busy.completed'),runExecuted:exists('busy.run')});

  currentCase='partial-typed-input';
  const partial=await makeTerminal('partial');
  const partialCmd=writeMarker('partial.typed');
  await nativeInput(partial,partialCmd);
  await sleep(400);
  const partialBefore=snapshot(partial);
  const partialAdmission=admission(partial,'partial-run',writeMarker('partial.run'),{seen:new Set(),pending:false});
  await until(()=>exists('partial.run')||state(partial).ends>0,8000,'partial run outcome');
  await sleep(200);
  await nativeInput(partial,'\r');
  await sleep(600);
  caseRecord(currentCase,{before:partialBefore,admission:partialAdmission,userTypedMarker:exists('partial.typed'),runMarker:exists('partial.run'),inputPreserved:exists('partial.typed'),note:'sendSequence supplies partial workbench input; no physical keyboard used.'});

  currentCase='foreground-interleaving';
  const race=await makeTerminal('race');
  const raceResults=[];
  for(let i=0;i<4;i++){
   const prefix='race-'+i;
   const before=snapshot(race);
   const nativeCommand=writeMarker(prefix+'.started')+'; Start-Sleep -Milliseconds 1700; '+writeMarker(prefix+'.completed');
   const nativePromise=nativeInput(race,nativeCommand+'\r');
   const dispatched=admission(race,'race-'+i,writeMarker(prefix+'.run'),{seen:new Set(),pending:false});
   await nativePromise;await sleep(2300);
   const after={foregroundStarted:exists(prefix+'.started'),foregroundCompleted:exists(prefix+'.completed'),runExecuted:exists(prefix+'.run')};
   raceResults.push({i,before,admission:dispatched,...after});emit('race-observation',raceResults[raceResults.length-1]);
   await nativeInput(race,'\u0003');await sleep(250);
  }
  caseRecord(currentCase,{trials:raceResults,interruptedTrials:raceResults.filter(r=>r.foregroundStarted&&!r.foregroundCompleted&&r.runExecuted).length,note:'Competing workbench input and API dispatch; exact interleaving recorded, not assumed.'});

  currentCase='stale-idle-observation';
  const stale=await makeTerminal('stale-observation');
  const idleAt=snapshot(stale);
  const foreground=writeMarker('stale.started')+'; Start-Sleep -Milliseconds 2200; '+writeMarker('stale.completed');
  await nativeInput(stale,foreground+'\r');
  await until(()=>exists('stale.started')&&state(stale).busy,8000,'foreground after idle observation');
  emit('observed-idle-now-busy',{idleAt,atDispatch:snapshot(stale)});
  await execute(stale,writeMarker('stale.run'),'negative-control-stale-idle');
  await sleep(2800);
  caseRecord(currentCase,{idleAt,foregroundStarted:exists('stale.started'),foregroundCompleted:exists('stale.completed'),runExecuted:exists('stale.run'),scope:'negative control bypasses current-busy guard; not proposed controller behavior'});

  currentCase='unavailable-integration';
  const unknown=vscode.window.createTerminal({name:'C2 disposable unknown',shellPath:config.shell,shellArgs:['-NoLogo'],cwd:config.fixture,env:{VSCODE_SHELL_INTEGRATION:'0'}});
  owned.push(unknown);states.set(unknown,{label:'unknown',ready:false,busy:false,closed:false,starts:0,ends:0});
  const unknownSnapshot=snapshot(unknown);
  const unknownAdmission=admission(unknown,'unknown-run',writeMarker('unknown.run'),{seen:new Set(),pending:false});
  await sleep(500);
  caseRecord(currentCase,{before:unknownSnapshot,admission:unknownAdmission,runExecuted:exists('unknown.run'),scope:'not-yet-ready real native terminal; not all integration-loss variants'});

  currentCase='terminal-closure';
  const closing=await makeTerminal('closure');closing.dispose();
  await until(()=>state(closing).closed,8000,'terminal closure');
  const closedAdmission=admission(closing,'closed-run',writeMarker('closed.run'),{seen:new Set(),pending:false});
  await sleep(500);
  caseRecord(currentCase,{admission:closedAdmission,runExecuted:exists('closed.run'),automaticRetry:false});

  currentCase='done';result.finishedAt=new Date().toISOString();result.experimentCompleted=true;
  emit('finished',{caseCount:result.cases.length});
 }catch(e){result.harnessErrors.push({case:currentCase,message:e.message,stack:e.stack});emit('harness-error',{message:e.message});throw e;}
 finally{
  for(const t of owned)if(!state(t)?.closed)t.dispose();
  await sleep(300);for(const l of listeners)l.dispose();
  fs.writeFileSync(config.results,JSON.stringify(result,null,2));
 }
};

